fn broadcast_arrays(a: Vec<i8>, b: Vec<i8>) -> (Vec<i8>, Vec<i8>) {
    let m = a.len();
    let n = b.len();
    let max_len = m.max(n);
    
    match (m, n) {
        (m, n) if m == n => (a, b),
        (1, _) => {
            let repeated_a = vec![a[0]; max_len];
            (repeated_a, b)
        }
        (_, 1) => {
            let repeated_b = vec![b[0]; max_len];
            (a, repeated_b)
        }
        _ => unreachable!("Arrays must be compatible: either same length or at least one has length 1"),
    }
}